param([string]$DataDirectory=(Join-Path ([Environment]::GetFolderPath('Desktop')) 'Movira_test_Video/hands'))
$ErrorActionPreference='Stop';Add-Type -AssemblyName System.Drawing
Add-Type -ReferencedAssemblies @('System.Drawing.Common','System.Drawing.Primitives','System.Private.Windows.GdiPlus','System.Private.Windows.Core','System.Runtime','System.Runtime.InteropServices') -TypeDefinition @'
using System;using System.Drawing;using System.Drawing.Imaging;using System.Runtime.InteropServices;
public static class MoviraFistPixels { public static byte[] Crop(Bitmap source,float x,float y,float side){using(var output=new Bitmap(64,64,PixelFormat.Format32bppArgb)){using(var g=Graphics.FromImage(output)){g.Clear(Color.Black);g.InterpolationMode=System.Drawing.Drawing2D.InterpolationMode.HighQualityBilinear;g.DrawImage(source,new RectangleF(0,0,64,64),new RectangleF(x,y,side,side),GraphicsUnit.Pixel);}var bits=output.LockBits(new Rectangle(0,0,64,64),ImageLockMode.ReadOnly,PixelFormat.Format32bppArgb);try{var bytes=new byte[16384];for(int row=0;row<64;row++)Marshal.Copy(bits.Scan0+row*bits.Stride,bytes,row*256,256);return bytes;}finally{output.UnlockBits(bits);}}}}
'@
$root=[IO.Path]::GetFullPath($DataDirectory);$folder=Join-Path $root 'fist-training';New-Item -ItemType Directory -Path $folder -Force | Out-Null
$manifest=Get-Content -LiteralPath (Join-Path $root 'hand-samples.json') -Raw | ConvertFrom-Json -AsHashtable
$sources=Get-Content -LiteralPath (Join-Path $root 'sources.json') -Raw | ConvertFrom-Json -AsHashtable
$records=[Collections.Generic.List[object]]::new();foreach($record in $manifest.records){$records.Add($record)}
Copy-Item -LiteralPath (Join-Path $root 'hands64.bgra') -Destination (Join-Path $folder 'hands64.bgra')
$stream=[IO.File]::Open((Join-Path $folder 'hands64.bgra'),[IO.FileMode]::Append);$random=[Random]::new(20261119);$added=0
try{for($index=0;$index -lt $sources.records.Count;$index+=4){$r=$sources.records[$index];$image=[Drawing.Bitmap]::new((Join-Path $root $r.file));try{$count=0;for($attempt=0;$attempt -lt 24 -and $count -lt 2;$attempt++){$side=[Math]::Min($image.Width,$image.Height)*(.13+$random.NextDouble()*.15);if($attempt -eq 0){$x=$image.Width*.5-$side/2;$y=$image.Height*.15-$side/2}else{$x=$random.NextDouble()*($image.Width-$side);$y=$random.NextDouble()*($image.Height-$side)};$x=[Math]::Max(0,$x);$y=[Math]::Max(0,$y);$overlap=$false;foreach($box in $r.boxes){$pad=.12*[Math]::Max($box[2]*$image.Width,$box[3]*$image.Height);if($x -lt ($box[0]+$box[2])*$image.Width+$pad -and $x+$side -gt $box[0]*$image.Width-$pad -and $y -lt ($box[1]+$box[3])*$image.Height+$pad -and $y+$side -gt $box[1]*$image.Height-$pad){$overlap=$true;break}};if($overlap){continue};$stream.Write([MoviraFistPixels]::Crop($image,$x,$y,$side));$records.Add(@{id=$r.id+'-hard-background-'+$count;split=$r.split;userId=$r.userId;positive=$false;gesture='hard-background';label=[double[]]::new(43);roi=@{x=$x;y=$y;side=$side}});$count++;$added++}}finally{$image.Dispose()};if($index%400 -eq 0){Write-Output "Reviewed $index source images; $added hard backgrounds"}}}finally{$stream.Dispose()}
$manifest.records=$records.ToArray();$manifest.note='Original hand crops plus patches avoiding all annotated hand boxes with padding. Automatic annotations may miss hands. Existing subject-separated splits retained.'
$manifest | ConvertTo-Json -Depth 20 -Compress | Set-Content -LiteralPath (Join-Path $folder 'hand-samples.json') -Encoding utf8
$dev=Join-Path $PSScriptRoot '../web/.dev';foreach($pair in @(@('hand-samples.json','fist-hand-samples.json'),@('hands64.bgra','fist-hands64.bgra'))){$dest=Join-Path $dev $pair[1];if(-not (Test-Path -LiteralPath $dest)){New-Item -ItemType HardLink -Path $dest -Target (Join-Path $folder $pair[0]) | Out-Null}}
Write-Output "Prepared $($records.Count) samples, including $added new background patches, in $folder"
